<!doctype html><html lang="{{ str_replace('_','-',app()->getLocale()) }}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $page->title }} — {{ config('fuelfree.company.name') }}</title><meta name="description" content="{{ $page->excerpt }}"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><style>:root{--bg:#031018;--panel:#071c28;--text:#eaf8fb;--muted:#8ba8b4;--accent:#45c8e8;--line:rgba(110,220,240,.14)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 82% -8%,rgba(54,188,220,.18),transparent 34%),linear-gradient(180deg,#031018,#061923 50%,#031018);color:var(--text);font-family:Inter,system-ui,-apple-system,sans-serif}a{color:inherit;text-decoration:none}.wrap{width:min(1180px,calc(100% - 32px));margin:auto}.site-header{position:sticky;top:0;z-index:30;background:rgba(3,16,24,.84);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.nav{min-height:68px;display:flex;align-items:center;justify-content:space-between;gap:15px}.brand{display:flex;align-items:center;gap:10px;font-weight:800;letter-spacing:.03em}.brand img{width:38px;height:38px;object-fit:contain;border-radius:10px}.brand span{color:var(--accent)}.menu-btn{display:none;width:42px;height:42px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.035);color:var(--text);font-size:17px}.menu{display:flex;align-items:center;gap:5px}.menu a{padding:9px 10px;border-radius:10px;color:var(--muted);font-size:11px;white-space:nowrap}.menu a:hover{background:rgba(69,200,232,.08);color:var(--text)}.menu i{margin-right:5px}.hero{position:relative;padding:78px 0 42px;overflow:hidden}.hero:after{content:"";position:absolute;right:5%;top:35px;width:220px;height:220px;border:1px solid rgba(69,200,232,.1);border-radius:50%;box-shadow:0 0 90px rgba(69,200,232,.08);animation:spin 16s linear infinite}.eyebrow{position:relative;z-index:1;color:var(--accent);font-size:10px;letter-spacing:.2em;text-transform:uppercase;font-weight:700}.hero h1{position:relative;z-index:1;font-size:clamp(38px,7vw,72px);line-height:1.02;margin:12px 0;letter-spacing:-.04em;max-width:900px}.excerpt{position:relative;z-index:1;color:var(--muted);line-height:1.8;font-size:16px;max-width:760px}.content{padding:30px;border:1px solid var(--line);border-radius:22px;background:linear-gradient(145deg,rgba(9,39,55,.72),rgba(5,22,32,.88));line-height:1.85;color:#c8d9df;box-shadow:0 18px 60px rgba(0,0,0,.12)}.content h2,.content h3{color:var(--text)}.content img{max-width:100%;height:auto;border-radius:14px}.content a{color:var(--accent)}.projects{padding:48px 0}.projects h2{font-size:28px;margin:7px 0 20px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{padding:20px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,rgba(9,39,55,.8),rgba(5,22,32,.9));transition:transform .2s,border-color .2s}.card:hover{transform:translateY(-3px);border-color:rgba(69,200,232,.3)}.card h3{margin:0 0 9px;font-size:18px}.meta{font-size:10px;color:var(--muted);line-height:1.8}.status{display:inline-flex;align-items:center;gap:5px;margin-top:12px;padding:5px 8px;border-radius:99px;background:rgba(88,201,232,.08);color:#8bd9eb;font-size:9px;text-transform:capitalize}.footer{margin-top:55px;padding:30px 0 55px;border-top:1px solid var(--line);color:#688792;font-size:10px}.reduced *{animation:none!important;transition:none!important}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:780px){.menu-btn{display:flex;align-items:center;justify-content:center}.menu{display:none;position:absolute;left:12px;right:12px;top:68px;padding:10px;flex-direction:column;align-items:stretch;background:rgba(4,19,27,.98);border:1px solid var(--line);border-radius:15px;box-shadow:0 20px 50px rgba(0,0,0,.35)}.menu.open{display:flex}.menu a{padding:12px}.hero{padding:52px 0 30px}.grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){.wrap{width:calc(100% - 24px)}.brand{font-size:13px}.hero h1{font-size:42px}.excerpt{font-size:14px}.content{padding:20px}.grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;scroll-behavior:auto!important;transition:none!important}}</style></head><body><header class="site-header"><div class="wrap nav"><a class="brand" href="{{ route('home') }}"><i class="fa-solid fa-bolt"></i>{{ config('fuelfree.company.name') }}<span> ENERGY</span></a><button class="menu-btn" type="button" aria-label="Open navigation" aria-expanded="false"><i class="fa-solid fa-bars"></i></button><nav class="menu" id="site-menu"><a href="{{ route('home') }}"><i class="fa-solid fa-house"></i>Home</a>@foreach($pages as $navPage)<a href="{{ route('cms.page',$navPage->slug) }}"><i class="fa-regular fa-file-lines"></i>{{ $navPage->title }}</a>@endforeach<a href="#projects"><i class="fa-solid fa-bolt"></i>Projects</a><a href="https://mail.fuelfreepowerplant.com" target="_blank" rel="noopener"><i class="fa-solid fa-envelope"></i>Webmail</a></nav></div></header><main><section class="hero"><div class="eyebrow">{{ config('fuelfree.company.name') }} · Corporate</div><h1>{{ $page->title }}</h1>@if($page->excerpt)<p class="excerpt">{{ $page->excerpt }}</p>@endif</section><article class="content">{!! $page->content !!}</article><section class="projects" id="projects"><div class="eyebrow">PROJECT PORTFOLIO</div><h2>Power &amp; Energy Projects</h2><div class="grid">@forelse($projects as $project)<a class="card" href="{{ route('projects.show',$project->slug) }}"><h3>{{ $project->name }}</h3><div class="meta">{{ $project->location ?: 'Location not specified' }}<br>{{ $project->capacity_kw !== null ? number_format((float)$project->capacity_kw,1).' kW' : 'Capacity not specified' }} · {{ $project->technology ?: 'Technology not specified' }}</div><span class="status"><i class="fa-solid fa-circle"></i>{{ $project->status }}</span></a>@empty<div class="card"><h3>No published projects</h3><div class="meta">Published project information will appear here when added from the administration dashboard.</div></div>@endforelse</div></section></main><footer class="footer">© {{ date('Y') }} {{ config('fuelfree.company.name') }}. All rights reserved.</footer><script>document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('.menu-btn'),m=document.querySelector('#site-menu');if(!b||!m)return;b.addEventListener('click',()=>{const open=m.classList.toggle('open');b.setAttribute('aria-expanded',open);b.setAttribute('aria-label',open?'Close navigation':'Open navigation');b.innerHTML=open?'<i class="fa-solid fa-xmark"></i>':'<i class="fa-solid fa-bars"></i>'});m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded','false');b.innerHTML='<i class="fa-solid fa-bars"></i>'}))});</script></body></html>